import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { ArrowLeft, BadgeCheck, Car, Check, Globe2, LogOut, Moon, Pencil, Phone, Star, Sun } from 'lucide-react';
import { formatShort } from '../data/mock';
import { useCourier } from '../lib/store';
import { StatCard, cn } from '../components/ui';

export const Profile = () => {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const { courier, orders, online, logout } = useCourier();
  const [confirm, setConfirm] = useState(false);
  const [dark, setDark] = useState(() => document.documentElement.classList.contains('dark'));

  const delivered = orders.filter((o) => o.status === 'delivered');
  const weekEarnings = delivered.reduce((s, o) => s + o.payout, 0);

  const cycleLang = () => {
    const next = i18n.language === 'uz' ? 'ru' : i18n.language === 'ru' ? 'en' : 'uz';
    i18n.changeLanguage(next);
  };

  const toggleTheme = () => {
    const next = !dark;
    setDark(next);
    document.documentElement.classList.toggle('dark', next);
    localStorage.setItem('maxshop-courier-theme', next ? 'dark' : 'light');
  };

  const doLogout = () => {
    setConfirm(false);
    logout();
    navigate('/login', { replace: true });
  };

  return (
    <div className="stagger space-y-4">
      <button onClick={() => navigate(-1)} className="flex items-center gap-1 text-[11px] font-extrabold text-[var(--muted)] transition hover:text-brand-600"><ArrowLeft size={13} /> {t('back')}</button>

      <div className="card relative overflow-hidden p-5">
        <span className="pointer-events-none absolute -right-14 -top-16 h-44 w-44 rounded-full bg-brand-400/25 blur-3xl" />
        <span className="pointer-events-none absolute -bottom-12 -left-12 h-36 w-36 rounded-full bg-lime-400/20 blur-3xl" />
        <div className="relative flex items-center gap-4">
          <span className="relative">
            <span className="absolute inset-0 rounded-[1.25rem] bg-amber-400/40 blur-lg animate-ping-slow" />
            <span className="accent-bg relative flex h-16 w-16 items-center justify-center rounded-[1.25rem] text-lg font-extrabold text-white shadow-glow">{courier.name.split(' ').map((n) => n[0]).slice(0, 2).join('')}</span>
          </span>
          <div className="min-w-0 flex-1">
            <p className="flex items-center gap-1.5 font-display text-base font-extrabold tracking-tight">{courier.name} <BadgeCheck size={15} className="text-brand-500" /></p>
            <p className="mt-1 flex items-center gap-2 text-[10px] font-bold text-[var(--muted)]">
              <span className="rounded-md border border-amber-400/30 bg-amber-400/15 px-1.5 py-0.5 text-amber-600 dark:text-amber-400">{courier.level}</span>
              {t('joined')}: {courier.joined}
            </p>
            <p className="mt-1 flex items-center gap-1 text-[10px] font-bold"><Star size={10} className="text-amber-400" /> <span className="text-gradient">{courier.rating}</span> · {courier.deliveries} {t('deliveries')}</p>
          </div>
          <button className="icon-btn h-9 w-9 transition"><Pencil size={14} /></button>
        </div>
      </div>

      <div>
        <h2 className="mb-2.5 font-display text-[15px] font-extrabold tracking-tight">{t('myStats')}</h2>
        <div className="stagger grid grid-cols-2 gap-2.5">
          <StatCard icon={<Star size={17} />} label={t('rating')} value={courier.rating} tone="violet" />
          <StatCard icon={<Check size={17} />} label={t('successRate')} value={`${courier.onTime}%`} />
          <StatCard icon={<span className="text-[13px] font-black">{t('today').slice(0, 1)}</span>} label={t('todayEarnings')} value={formatShort(weekEarnings)} tone="amber" />
          <StatCard icon={<Check size={17} />} label={t('acceptanceRate')} value={`${courier.acceptance}%`} tone="sky" />
        </div>
      </div>

      <div className="card divide-y">
        <button onClick={cycleLang} className="flex w-full items-center justify-between px-4 py-3.5 transition hover:bg-[var(--surface-2)] first:rounded-t-[1.5rem]">
          <span className="flex items-center gap-3 text-[11px] font-extrabold"><span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-sky-400/15 text-sky-600 dark:text-sky-400"><Globe2 size={15} /></span> {t('language')}</span>
          <span className="rounded-lg bg-[var(--surface-2)] px-2 py-1 text-[10px] font-extrabold">{i18n.language.toUpperCase()}</span>
        </button>
        <button onClick={toggleTheme} className="flex w-full items-center justify-between px-4 py-3.5 transition hover:bg-[var(--surface-2)]">
          <span className="flex items-center gap-3 text-[11px] font-extrabold"><span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-violet-400/15 text-violet-600 dark:text-violet-400">{dark ? <Moon size={15} /> : <Sun size={15} />}</span> {t('theme')}</span>
          <span className="flex items-center gap-2 text-[10px] font-extrabold text-[var(--muted)]">
            {dark ? t('dark') : t('light')}
            <span className={cn('flex h-4 w-7 items-center rounded-full px-0.5 transition', dark ? 'accent-bg justify-end' : 'bg-[var(--surface-3)] justify-start')}>
              <span className="h-3 w-3 rounded-full bg-white shadow" />
            </span>
          </span>
        </button>
        <a href={`tel:${courier.phone.replace(/\s/g, '')}`} className="flex w-full items-center justify-between px-4 py-3.5 transition hover:bg-[var(--surface-2)]">
          <span className="flex items-center gap-3 text-[11px] font-extrabold"><span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-brand-500/10 text-brand-600 dark:text-brand-400"><Phone size={15} /></span> {t('phoneNumber')}</span>
          <span className="text-[10px] font-bold text-[var(--muted)]">{courier.phone}</span>
        </a>
        <div className="flex w-full items-center justify-between px-4 py-3.5 last:rounded-b-[1.5rem]">
          <span className="flex items-center gap-3 text-[11px] font-extrabold"><span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-amber-400/15 text-amber-600 dark:text-amber-400"><Car size={15} /></span> {t('vehicleType')}</span>
          <span className="text-[10px] font-bold text-[var(--muted)]">{courier.vehicle} · {courier.plate}</span>
        </div>
      </div>

      {confirm ? (
        <div className="card animate-pop border-rose-400/40 p-4 text-center">
          <p className="text-[11px] font-extrabold">{t('logoutConfirm')}</p>
          <div className="mt-3 grid grid-cols-2 gap-2">
            <button onClick={() => setConfirm(false)} className="btn-secondary btn-sm">{t('cancel')}</button>
            <button onClick={doLogout} className="btn-danger btn-sm">{t('yes')}</button>
          </div>
        </div>
      ) : (
        <button onClick={() => setConfirm(true)} className="flex w-full items-center justify-center gap-2 rounded-2xl border bg-[var(--surface-solid)] px-4 py-3.5 text-[11px] font-extrabold text-rose-500 transition hover:border-rose-400/40 hover:bg-rose-500/5">
          <LogOut size={14} /> {t('logout')}
        </button>
      )}

      <p className="pb-2 text-center text-[9px] font-bold text-[var(--muted)]">
        {online ? t('online') : t('offline')} · © 2026 MaxSHOP
      </p>
    </div>
  );
};
